-- Spring Batch 테이블은 spring.batch.jdbc.initialize-schema: always 설정으로 자동 생성됨
-- =========================================================
-- FitMe DB 통합 더미 데이터 (자동 생성)
-- 생성일시: 2026. 2. 4. 오후 9:36:26
-- =========================================================

BEGIN;

-- FK 제약 조건 임시 비활성화 (데이터 삽입 순서 문제 방지)
SET session_replication_role = 'replica';

-- 0. updated_at 자동 갱신 함수 (ERD 트리거에서 사용)
CREATE OR REPLACE FUNCTION set_updated_at()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;

-- 0-1. report 스키마 보강 (updated_at 없을 때만 추가, NOTICE 방지)
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'report' AND column_name = 'updated_at'
  ) THEN
    ALTER TABLE public.report ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now();
  END IF;
END $$;

DROP TRIGGER IF EXISTS trg_set_updated_at_report ON public.report;
CREATE TRIGGER trg_set_updated_at_report
  BEFORE UPDATE ON public.report
  FOR EACH ROW
  EXECUTE FUNCTION set_updated_at();

-- 0-2. moderation_action 스키마 보강 (updated_at 없을 때만 추가, NOTICE 방지)
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'moderation_action' AND column_name = 'updated_at'
  ) THEN
    ALTER TABLE public.moderation_action ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now();
  END IF;
END $$;

DROP TRIGGER IF EXISTS trg_set_updated_at_moderation_action ON public.moderation_action;
CREATE TRIGGER trg_set_updated_at_moderation_action
  BEFORE UPDATE ON public.moderation_action
  FOR EACH ROW
  EXECUTE FUNCTION set_updated_at();

