-- =========================================================
-- 2-1. [업종 Alias] Industry Alias & Vocab
-- =========================================================
-- 확장 설치
CREATE EXTENSION IF NOT EXISTS pg_trgm;

-- 기존 있으면 삭제(제약/인덱스 포함)
DROP MATERIALIZED VIEW IF EXISTS public.industry_vocab;
DROP TABLE IF EXISTS public.industry_alias CASCADE;

-- 업종 alias 테이블
CREATE TABLE IF NOT EXISTS public.industry_alias (
  alias        text PRIMARY KEY,
  canonical    text NOT NULL,
  display_name text NULL,
  is_active    boolean NOT NULL DEFAULT true,
  created_at   timestamptz NOT NULL DEFAULT now(),
  updated_at   timestamptz NOT NULL DEFAULT now()
);

-- 검색 성능 인덱스
CREATE INDEX IF NOT EXISTS ix_industry_alias_alias_trgm
ON public.industry_alias USING gin (alias gin_trgm_ops)
WHERE is_active;

CREATE INDEX IF NOT EXISTS ix_industry_alias_canonical_trgm
ON public.industry_alias USING gin (canonical gin_trgm_ops)
WHERE is_active;

-- vocab (fuzzy 후보용) - alias/canonical 둘 다 토큰화
CREATE MATERIALIZED VIEW IF NOT EXISTS public.industry_vocab AS
WITH tokens AS (
  SELECT lower(btrim(tok)) AS token
  FROM public.industry_alias ia
  CROSS JOIN LATERAL regexp_split_to_table(
    coalesce(ia.alias,'') || ',' || coalesce(ia.canonical,''),
    's[,/|]+s'
  ) AS tok
  WHERE ia.is_active
)
SELECT token, COUNT(*)::bigint AS cnt
FROM tokens
WHERE token <> ''
GROUP BY token;

CREATE UNIQUE INDEX IF NOT EXISTS ux_industry_vocab_token
ON public.industry_vocab (token);

CREATE INDEX IF NOT EXISTS ix_industry_vocab_token_trgm
ON public.industry_vocab USING gin (token gin_trgm_ops);

