INSERT INTO employer (
    employer_id, employer_uid, name, logo_url, industry, founded_year, employee_count,
    location, description, culture, benefits, tech_stack,
    contact_email, contact_phone, website_url, status, created_at, updated_at
) VALUES (
    50, gen_random_uuid(), '이데아게임즈 주식회사', 'https://cdn.fitme.co.kr/employers/50/logo.png', 'Fintech', 2017, 3000,
    '부산광역시 해운대구', '이데아게임즈 주식회사 - Fintech', '[조직] 수평적 조직문화와 자유로운 의견 개진을 중시합니다. 직급보다 역할과 책임으로 소통하며, 빠른 의사결정과 실행을 선호합니다. [실행] 실패를 두려워하지 않고 시도하고, 회고를 통해 배움을 공유합니다. [협업] 크로스펑셔널 팀 구성, 슬랙·노션 등으로 투명한 정보 공유, 정기적 올핸즈로 방향성을 맞춥니다.', '[보상] 스톡옵션 부여 및 성과에 따른 스톡그랜트, 연봉 상위 10% 수준 유지, 분기별 성과급(최대 200%) 지급. [근무] 유연근무제(코어타임 11~15시), 재택·원격 근무 주 2일, 연차 외 리프레시 휴가 5일. [지원] 최신 개발 장비 지급(MacBook Pro 등), 도서·강의·자격증 비용 전액 지원, 사내 카페 무료 이용, 점심 식대 지원.', 'MySQL, TailwindCSS, Node.js, HuggingFace, FastAPI, Kubernetes',
    'hr@.com', '01003838296', 'https://.co.kr', 'ACTIVE', now(), now()
)
