-- ================================================================
-- FitMe 실제 기업 로고 URL 업데이트 스크립트 V2
-- fitme_ALL_IN_ONE_9.sql의 500개 기업 중 유명 기업 로고 적용
-- Wikimedia Commons 실제 로고 + DiceBear 아바타 통일
-- 실행: psql -f UPDATE_REAL_COMPANY_LOGOS_V2.sql
-- ================================================================

BEGIN;

-- ================================================================
-- 1. 주식회사 크래프톤 (employer_id: 399)
-- ================================================================
UPDATE employer
SET 
    logo_url = 'https://upload.wikimedia.org/wikipedia/commons/thumb/2/29/Krafton_Logo.png/200px-Krafton_Logo.png',
    updated_at = NOW()
WHERE name = '주식회사 크래프톤';

-- ================================================================
-- 2. 한국마이크로소프트 유한회사 (employer_id: 298)
-- ================================================================
UPDATE employer
SET 
    logo_url = 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/44/Microsoft_logo.svg/200px-Microsoft_logo.svg.png',
    updated_at = NOW()
WHERE name = '한국마이크로소프트 유한회사';

-- ================================================================
-- 3. 블리자드엔터테인먼트유한회사 (employer_id: 479)
-- ================================================================
UPDATE employer
SET 
    logo_url = 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b2/Blizzard_Entertainment_Logo.svg/200px-Blizzard_Entertainment_Logo.svg.png',
    updated_at = NOW()
WHERE name = '블리자드엔터테인먼트유한회사';

-- ================================================================
-- 4. 구글클라우드코리아 유한회사 (employer_id: 104)
-- ================================================================
UPDATE employer
