-- ================================================================
-- 나머지 모든 기업: DiceBear API 기반 로고로 업데이트
-- 회사명을 seed로 사용하여 고유한 아바타 생성 (한글 지원)
-- ================================================================
UPDATE employer
SET 
    logo_url = 'https://api.dicebear.com/7.x/initials/png?seed=' || 
               REPLACE(name, ' ', '+') || 
               '&backgroundColor=' ||
               CASE 
                   WHEN employer_id % 20 = 0 THEN '0d8abc'
                   WHEN employer_id % 20 = 1 THEN '28a745'
                   WHEN employer_id % 20 = 2 THEN '6f42c1'
                   WHEN employer_id % 20 = 3 THEN 'dc3545'
                   WHEN employer_id % 20 = 4 THEN 'fd7e14'
                   WHEN employer_id % 20 = 5 THEN '17a2b8'
                   WHEN employer_id % 20 = 6 THEN '6610f2'
                   WHEN employer_id % 20 = 7 THEN 'e83e8c'
                   WHEN employer_id % 20 = 8 THEN '20c997'
                   WHEN employer_id % 20 = 9 THEN 'ff6b6b'
                   WHEN employer_id % 20 = 10 THEN '4ecdc4'
                   WHEN employer_id % 20 = 11 THEN '45b7d1'
                   WHEN employer_id % 20 = 12 THEN '96ceb4'
                   WHEN employer_id % 20 = 13 THEN 'ffeaa7'
                   WHEN employer_id % 20 = 14 THEN 'dda0dd'
                   WHEN employer_id % 20 = 15 THEN 'f39c12'
                   WHEN employer_id % 20 = 16 THEN '1abc9c'
                   WHEN employer_id % 20 = 17 THEN '9b59b6'
                   WHEN employer_id % 20 = 18 THEN 'e74c3c'
                   ELSE '3498db'
               END ||
               '&size=200',
    updated_at = NOW()
WHERE (logo_url IS NULL 
    OR logo_url LIKE '%cdn.fitme.co.kr%'
    OR logo_url = '')
  AND deleted_at IS NULL;

COMMIT;

-- ================================================================
-- 업데이트 결과 확인
-- ================================================================
SELECT employer_id, name, 
       CASE 
           WHEN logo_url LIKE '%wikimedia%' THEN '✓ Wikimedia'
           WHEN logo_url LIKE '%dicebear%' THEN '○ DiceBear'
           ELSE '? Other'
       END as logo_type,
       SUBSTRING(logo_url FROM 1 FOR 80) as logo_url_preview
FROM employer 
WHERE deleted_at IS NULL
ORDER BY 
    CASE WHEN logo_url LIKE '%wikimedia%' THEN 0 ELSE 1 END,
    employer_id
LIMIT 60;


