SELECT setval(pg_get_serial_sequence('employer', 'employer_id'), (SELECT COALESCE(MAX(employer_id), 1) FROM employer));
SELECT setval(pg_get_serial_sequence('employer_member', 'employer_member_id'), (SELECT COALESCE(MAX(employer_member_id), 1) FROM employer_member));
