SELECT setval(pg_get_serial_sequence('wallet_ledger', 'ledger_id'), (SELECT COALESCE(MAX(ledger_id), 1) FROM wallet_ledger));
SELECT setval(pg_get_serial_sequence('orders', 'order_id'), (SELECT COALESCE(MAX(order_id), 1) FROM orders));
SELECT setval(pg_get_serial_sequence('resume', 'resume_id'), (SELECT COALESCE(MAX(resume_id), 1) FROM resume));
SELECT setval(pg_get_serial_sequence('job_posting', 'job_id'), (SELECT COALESCE(MAX(job_id), 1) FROM job_posting));
SELECT setval(pg_get_serial_sequence('job_application', 'application_id'), (SELECT COALESCE(MAX(application_id), 1) FROM job_application));
